# -*- coding: utf-8 -*-
import logging

from taf.fdsw.rc.interfaces.FDSW21C.autoconnection import AutoConfiguration21C
from taf.fdsw.rc.schemas.FDSW21D.autoconnection import Site_Identification21D
from taf.fdsw.rc.schemas.FDSW21D.autoconnection_parameters_builder_21d import \
    AutoconnectionParametersBuilder21D

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoConfiguration21D(AutoConfiguration21C):

    param_builder = AutoconnectionParametersBuilder21D

    def get_site_identification_info(self, timeout=10):
        get_site_identification_info = self._client.send(
            method='config.identification.fetch',
            timeout=timeout,
            parameters={})
        get_site_identification_info = Site_Identification21D.from_object_dict(data=get_site_identification_info.data)
        return get_site_identification_info.to_dict()

    def enable_gnss_constellations(self, constellations, timeout=10):
        constellations = [item.upper() for item in constellations]
        set_site_identification_response = self._client.send(
            method='config.identification.update',
            timeout=timeout,
            parameters={
                'gnss': {
                    'constellationsEnabled': constellations,
                }})
        return set_site_identification_response.data

    def get_supported_gnss_constellations(self, timeout=10):
        return self.get_site_identification_info(
            timeout=timeout)['gnss']['constellationsSupported']

    def get_gnss_constellations_status(self, timeout=10):
        return self.get_site_identification_info(
            timeout=timeout)['gnss']['status']

    def enable_autoconfiguration_service(self, timeout):
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"autoconfiguration": {"mode": "Automatic"}}})

    def disable_autoconfiguration_service(self, timeout):
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"autoconfiguration": {'mode': 'Manual'}}})

    def enable_autoconnection_service(self, timeout=10):
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"autoconnection": {"mode": "Automatic"}}})

    def disable_autoconnection_service(self, timeout=10):
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"autoconnection": {"mode": "Manual"}}})
